      status: "pending" | "in_progress" | "completed";
    })[];
  } & Record<string, JsonValue>;
  /** Control which tool schemas are injected into the model context of this session. Actions: "list" (every visible tool with its hidden state), "hide" (remove the named tools from the model context — they also become uncallable via UNKNOWN_TOOL), "show" (restore the named tools), "reset" (clear the hidden set). The reserved tools run_code and tool_visibility can never be hidden. Changes persist to the plugin state file and take effect on the next model step. */
  tool_visibility: {
    /** What to do: list | hide | show | reset. */
    action: "list" | "hide" | "show" | "reset";
    /** Tool names the action applies to (required for hide/show; ignored for list/reset). */
    tools?: string[];
  };
